chatSettings.xinshengCustomCss:
/* =========================================================
   糯叽机日记卡片 CSS · v8
   ---------------------------------------------------------
   请整份替换旧 CSS。
   此版不再使用代理按钮。
   五个真实按钮由 JS 直接 fixed 到卡片顶部。
   ========================================================= */


/* =========================
   卡片
   ========================= */

.xt-root {
    --xt-yellow: #eab308;

    position: relative !important;

    background: #fff !important;
    color: #333 !important;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Helvetica Neue",
        Arial,
        sans-serif !important;

    border: none !important;
    border-radius: 16px !important;

    box-shadow:
        0 4px 20px
        rgba(0, 0, 0, .08) !important;

    /* 顶部真实按钮区域 */
    padding-top: 58px !important;

    padding-bottom: 20px !important;

    box-sizing: border-box !important;
}


/* =========================
   通用文字
   ========================= */

.xt-text {
    display: block;

    background: transparent !important;
    border: none !important;
    box-shadow: none !important;

    padding: 0 !important;

    color: #333;

    font-size: 15px;

    margin-bottom: 16px;

    box-sizing: border-box;
}


/* =========================================================
   原站五个真实按钮
   ---------------------------------------------------------
   不复制
   不隐藏
   不改 DOM 父子关系
   只是改变它们的视觉位置
   ========================================================= */

.xt-relocated-native-action {
    position: fixed !important;

    left:
        var(--xt-native-left)
        !important;

    top:
        var(--xt-native-top)
        !important;

    width: 28px !important;
    height: 28px !important;

    min-width: 28px !important;
    min-height: 28px !important;

    margin: 0 !important;
    padding: 0 !important;

    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    background: transparent !important;

    border: none !important;
    border-radius: 0 !important;

    box-shadow: none !important;

    color: #eab308 !important;

    cursor: pointer !important;

    z-index: 2147483000 !important;

    box-sizing: border-box !important;

    transform: none !important;
}


/* 图标尺寸 */
.xt-relocated-native-action svg {
    display: block !important;

    width: 21px !important;
    height: 21px !important;

    stroke: currentColor !important;

    pointer-events: none !important;
}


/* × */
.xt-relocated-native-action[
    data-xt-native-action="close"
] svg {
    width: 22px !important;
    height: 22px !important;
}


/* 删除 */
.xt-relocated-native-action[
    data-xt-native-action="delete"
] {
    color: #e57373 !important;
}


/* 点击反馈 */
.xt-relocated-native-action:active {
    opacity: .45 !important;
    transform: scale(.88) !important;
}


/* 原来底部工具栏的父容器只收掉空白。
   不隐藏父容器，不影响按钮事件。 */
.xt-native-toolbar-shell {
    height: 0 !important;
    min-height: 0 !important;

    margin-top: 0 !important;
    margin-bottom: 0 !important;

    padding-top: 0 !important;
    padding-bottom: 0 !important;

    overflow: visible !important;
}


